def make(p=None):p=p or package();INPUTS.append(deepcopy(p));return Engine.create(Compiler().compile(p),seed=8882500)
def capture(s,name):CAPTURES.append({'case':name,'checkpoint':s.checkpoint(),'events':thaw(tuple(s.session.events)),'replay':s.export_replay()})
def test_original_false_request_keeps_source_on_wave0_and_preserves_remainingbirth_post_pre_cp_head(tmp_path):
 s=make();s.submit({'action':'skill','source':'director','ability':'ability/peer/kill'},at=6);s.advance(9);assert not s.ctx.active('managed_source') and s.ctx.resources.current('managed_source','hp')==0
 pin=write_ordered(tmp_path/'false9.json',s.checkpoint());r=Engine.restore(s.program,load_bound(tmp_path/'false9.json',pin));s.advance(16);r.advance(16);h=replay(s.program,s.export_replay());capture(s,'false');assert s.checkpoint()==r.checkpoint()==h.checkpoint()
 state=s.ctx.state()['timeline'];assert state['wave_index']==1 and state['members']['3']['wave']==0 and not state.get('tracking_requests',{})
 assert s.ctx.resources.current('managed_source','hp')==1250 and s.ctx.active('managed_source')
 births=[(e['time'],e['payload']['target']) for e in s.session.events if e['type']=='entity.created'];assert (3,3) in births and (10,4) in births and (19,5) in births
